{"pou_name":"FB_MovingAverage","pou_type":"FUNCTION_BLOCK","declaration":"FUNCTION_BLOCK FB_MovingAverage
VAR_INPUT
    cyclicExecution : BOOL;
    trigger : BOOL;
    value : LREAL;
    windowSize : INT;
    reset : BOOL;
END_VAR
VAR_OUTPUT
    average : LREAL;
    windowSizeReached : BOOL;
    error : BOOL;
    status : WORD;
END_VAR
VAR
    samples : ARRAY[1..100] OF LREAL;
    sampleCount : INT := 0;
    writeIndex : INT := 1;
    totalSum : LREAL := 0.0;
    triggerPrevious : BOOL;
    lastWindowSize : INT := 0;
END_VAR","implementation":"IF (windowSize < 1) OR (windowSize > 100) THEN
    error := TRUE;
    status := 16#8200;
ELSE
    error := FALSE;
    status := 16#0000;
END_IF;

IF reset THEN
    sampleCount := 0;
    writeIndex := 1;
    totalSum := 0.0;
    average := 0.0;
    windowSizeReached := FALSE;
    lastWindowSize := 0;
END_IF;

IF (NOT error) AND (NOT reset) THEN
    IF (windowSize <> lastWindowSize) THEN
        sampleCount := 0;
        writeIndex := 1;
        totalSum := 0.0;
        average := 0.0;
        windowSizeReached := FALSE;
    END_IF;
    lastWindowSize := windowSize;

    IF cyclicExecution OR (trigger AND NOT triggerPrevious) THEN
        IF sampleCount < windowSize THEN
            samples[writeIndex] := value;
            totalSum := totalSum + value;
            sampleCount := sampleCount + 1;
        ELSE
            totalSum := totalSum + value - samples[writeIndex];
            samples[writeIndex] := value;
        END_IF;

        writeIndex := writeIndex + 1;
        IF writeIndex > windowSize THEN
            writeIndex := 1;
        END_IF;

        IF sampleCount > 0 THEN
            average := totalSum / INT_TO_LREAL(sampleCount);
        END_IF;

        windowSizeReached := (sampleCount = windowSize);
    END_IF;
END_IF;

triggerPrevious := trigger;"}

